/**
 * Block-exact generator of the main-task trial pools.
 *
 * One condition's 24-trial pool is generated as TWO 12-trial halves (Main A and
 * Main B), never as a 24-pool that is partitioned afterwards, so that the
 * counterbalance below holds inside every 60-trial block, for every condition,
 * and not only across the pool. Every half is generated by the same procedure
 * for all five conditions (d_only and t_only have memory items only, i_only has
 * stars only, i_d and i_t have both), so the label x serial-position structure
 * of single and dual conditions is identical.
 *
 * EXACT per 12-trial half, per condition:
 *   1. M / S slot occupancy: 6 trials with an M at every slot (6 trials with an S).
 *      A half is built from 6 of the 7 complement pairs of the 14 valid strings
 *      (pair omitted per half, see OMITTABLE).
 *   2. Memory items: on / off = 3 / 3 among the 6 trials that have a memory item at
 *      each slot; 6 / 6 per memory ordinal (1st, 2nd, 3rd item).
 *   3. Stars: on / off = 3 / 3 among the 6 trials that have a star at each slot;
 *      6 / 6 per star ordinal; 3 / 3 per rotation stratum.
 *   4. Probe type x test position: 3 per cell; encoding ordinal x test position:
 *      4 per cell; target class x ordinal x test position: 1 per cell; 3 probed
 *      targets per slot; 0-3 targets per trial with the histogram (2,4,4,2) in one half and
 *      (1,5,5,1) in the other (the pool has (3,9,9,3) trials with 0/1/2/3 targets; a trial
 *      may thus have 3 foils or 0 foils; the half is drawn like item 6); no probe type 3
 *      times in a trial (cap kept).
 *   5. Rotation: 2 angles per stratum (6 strata), 6 negative + 6 non-negative;
 *      background shade 6 white + 6 gray.
 *   6. The per-trial number of on-pattern items (memory, and separately stars) has
 *      the histogram (2,4,4,2) in one half and (1,5,5,1) in the other, i.e. the
 *      pool has (3,9,9,3) trials with 0/1/2/3 on-items. The count is NOT forced
 *      into 1..2 (that would be a deterministic cue).
 *   7. Crossings with the page background (shade; 6 trials of each shade):
 *      memory label x shade 9 on / 9 off (18 memory items per shade), star label x
 *      shade 9 / 9; probe type x shade 4 or 5 per cell and probe type x test
 *      position x shade 1 or 2 per cell (the other half holds the complement).
 *   8. Memory label x rotation stratum (d_only, i_d, i_t): exactly 3 on-pattern
 *      items per stratum. The strata are assigned AFTER the memory labels, as pairs
 *      of trials whose memory on-counts sum to 3.
 * EXACT per 24-trial pool: all of the above doubled; probed T_on / T_off = 3 / 3
 * at every slot (per half 1 or 2 T_on: pattern a in one half, 3 - a in the other);
 * probe type x shade 9 per cell, probe type x test position x shade 3 per cell
 * (the halves are complements); the 14 strings are all used (at most twice);
 * 4 distinct angles per stratum split 2 / 2; 12 negative angles.
 *
 * NOT exact, by design: which grid CELL carries an encoded dot / tone, a star or a
 * foil probe. These are drawn independently and uniformly for every trial (src/
 * scheduler/cell-draw.js): equal in expectation, not equal per pool. Exact
 * per-pool cell-usage balancing (and greedy least-used picking) would make
 * target-vs-foil predictable from the participant-visible cell history (a held-out
 * classifier reached 69 % accuracy against 50 % for independent draws).
 *
 * Hard rules kept: a foil is never on an encoded cell and foils of a trial are
 * distinct; stars / dummies avoid every item and foil cell of the trial; encoded
 * tones and foil tones are at least MIN_TONE_GAP_RANKS ranks from each other.
 *
 * Every random draw comes from the supplied seeded PRNG, so a half (and the
 * pool) is reproducible from the seed. A search that does not converge throws a
 * `Retry` internally; the half is redrawn from the same stream (bounded), and
 * the pool is redrawn if a half cannot be completed.
 */
import { enumerateValidSequences } from './within-trial.js';
import { ROTATION_STRATA, rotationStratumIndex } from './rotation-balance.js';
import { BACKGROUND_SHADES } from '../visuals/colour-palette.js';
import { drawEncodedCells, drawFoilCells, drawStarCells, drawDummyCells } from './cell-draw.js';

export const BALANCED_TYPES = Object.freeze(['d_only', 't_only', 'i_only', 'i_d', 'i_t']);
export const HALF_SIZE = 12;
export const MAX_HALF_TRIES = 60;
export const MAX_POOL_TRIES = 8;

const hasMemory = (t) => t !== 'i_only';
const hasStars = (t) => t.startsWith('i_');
const isTone = (t) => t === 't_only' || t === 'i_t';
const hasRotation = (t) => t !== 't_only';

const T_ON = 0;
const T_OFF = 1;
const F_ON = 2;
const F_OFF = 3;
const TYPE_NAMES = Object.freeze(['T_on', 'T_off', 'F_on', 'F_off']);
const N = HALF_SIZE;

export class Retry extends Error {}

/* A global, deterministic attempt budget (an attempt COUNT, never wall-clock time, so
 * a plan stays reproducible from its seed). Every half attempt, pool attempt and plan
 * attempt of one generateMainPlan call spends one unit; when the budget is spent the
 * call throws, so a degenerate random stream cannot stall the page behind the nested
 * retry caps. */
export class AttemptBudgetExceeded extends Error {}
export function createAttemptBudget(max) {
  const b = {
    max,
    used: 0,
    spend(what) {
      if (++b.used > max) {
        throw new AttemptBudgetExceeded(
          `generateMainPlan: attempt budget of ${max} exhausted (last step: ${what}); ` +
            `the random stream does not produce a valid balanced plan`
        );
      }
    },
  };
  return b;
}
const fail = (m) => {
  throw new Retry(m);
};
const sum = (a) => a.reduce((x, y) => x + y, 0);
const range = (n) => Array.from({ length: n }, (_, i) => i);

/* ---------- sequences: the 14 valid strings are 7 complement pairs ---------- */
const PAIRS = (() => {
  const valid = enumerateValidSequences();
  const byKey = new Map(valid.map((s) => [s.join(''), s]));
  const seen = new Set();
  const out = [];
  for (const s of valid) {
    if (seen.has(s.join(''))) continue;
    const c = byKey.get(s.map((x) => (x === 'M' ? 'S' : 'M')).join(''));
    seen.add(s.join(''));
    seen.add(c.join(''));
    out.push([s, c]);
  }
  return out;
})();

/* Only these four pairs (and so their complements) may be left out of a half. An
 * integer-program check of the design showed that leaving out any of the other
 * three pairs restricts which per-slot T_on patterns a half can realise, which
 * would break the pool-level probed T_on / T_off = 3 / 3 at every slot. */
const OMITTABLE = ['SMSMSM', 'SMSMMS', 'SMMSSM', 'SMMSMS'].map((k) =>
  PAIRS.findIndex((p) => p.some((x) => x.join('') === k))
);

/* ---------- probe plan: 12 rows, exact marginals ---------- */
function trialProbeBad(types) {
  const c = [0, 0, 0, 0];
  types.forEach((t) => c[t]++);
  return Math.max(...c) > 2 ? 1 : 0;
}
/* number of trials with 0 / 1 / 2 / 3 targets */
function targetHist(types) {
  const h = [0, 0, 0, 0];
  types.forEach((r) => h[r.filter((x) => x <= 1).length]++);
  return h;
}
const histDev = (types, want) => {
  const h = targetHist(types);
  return sum(h.map((x, k) => Math.abs(x - want[k])));
};
const PERMS = (() => {
  const o = [];
  for (const a of [0, 1, 2])
    for (const b of [0, 1, 2])
      for (const c of [0, 1, 2]) if (a !== b && b !== c && a !== c) o.push([a, b, c]);
  return o;
})();

function genProbePlan(rng, st, want) {
  for (let att = 0; ; att++) {
    st.planTries++;
    if (att > 200) fail('probe types');
    const cols = range(3).map(() => rng.shuffle([0, 0, 0, 1, 1, 1, 2, 2, 2, 3, 3, 3]));
    const types = range(N).map((t) => [cols[0][t], cols[1][t], cols[2][t]]);
    /* cost = trials with a probe type 3 times + deviation of the targets-per-trial histogram from the
     * pinned one; swaps inside a column keep the exact column margins */
    const total = () => sum(types.map(trialProbeBad)) + histDev(types, want);
    let cost = total();
    for (let step = 0; step < 4000 && cost > 0; step++) {
      const j = rng.int(3);
      const a = rng.int(N);
      const b = rng.int(N);
      if (a === b || types[a][j] === types[b][j]) continue;
      [types[a][j], types[b][j]] = [types[b][j], types[a][j]];
      const after = total();
      if (after <= cost) cost = after;
      else [types[a][j], types[b][j]] = [types[b][j], types[a][j]];
    }
    if (cost > 0) continue;
    /* encoding ordinal per test position: every (class, ordinal, position) cell once */
    const permCost = (perm) => {
      let c = 0;
      for (const cls of [0, 1])
        for (let j = 0; j < 3; j++) {
          const cnt = [0, 0, 0];
          for (let t = 0; t < N; t++) if (types[t][j] === cls) cnt[perm[t][j]]++;
          c += cnt.reduce((x, y) => x + Math.abs(y - 1), 0);
        }
      return c;
    };
    for (let rs = 0; rs < 20; rs++) {
      const perm = rng.shuffle([...PERMS, ...PERMS]).map((p) => p.slice());
      let pc = permCost(perm);
      for (let step = 0; step < 3000 && pc > 0; step++) {
        const a = rng.int(N);
        const b = rng.int(N);
        if (a === b) continue;
        [perm[a], perm[b]] = [perm[b], perm[a]];
        const nc = permCost(perm);
        if (nc <= pc) pc = nc;
        else [perm[a], perm[b]] = [perm[b], perm[a]];
      }
      if (pc === 0) return { types, perm };
    }
  }
}

/* ---------- pairing of probe-plan rows with sequence rows ---------- */
/* Exact feasibility of the label layer: a labelling of the memory items exists
 * with 3 on per slot AND 6 on per ordinal, given the pinned (probed target)
 * items. Max-flow shortfall; 0 <=> such a labelling exists. */
function flowShortfall(mslots, plan, sg) {
  const u = range(6).map(() => [0, 0, 0]);
  const pinOnS = Array(6).fill(0);
  const pinOnE = [0, 0, 0];
  for (let r = 0; r < N; r++) {
    const t = sg[r];
    const isPin = [false, false, false];
    const pinVal = [0, 0, 0];
    for (let j = 0; j < 3; j++) {
      const ty = plan.types[r][j];
      if (ty <= 1) {
        isPin[plan.perm[r][j]] = true;
        pinVal[plan.perm[r][j]] = ty === T_ON ? 1 : 0;
      }
    }
    for (let e = 0; e < 3; e++) {
      const s = mslots[t][e];
      if (isPin[e]) {
        if (pinVal[e]) {
          pinOnS[s]++;
          pinOnE[e]++;
        }
      } else u[s][e]++;
    }
  }
  const f = pinOnS.map((p) => 3 - p);
  const col = pinOnE.map((p) => 6 - p);
  if (f.some((x) => x < 0) || col.some((x) => x < 0)) return 9;
  /* nodes: 0 source, 1..6 slots, 7..9 ordinals, 10 sink */
  const C = range(11).map(() => Array(11).fill(0));
  for (let s = 0; s < 6; s++) {
    C[0][1 + s] = f[s];
    for (let e = 0; e < 3; e++) C[1 + s][7 + e] = u[s][e];
  }
  for (let e = 0; e < 3; e++) C[7 + e][10] = col[e];
  let flow = 0;
  for (;;) {
    const prev = Array(11).fill(-1);
    prev[0] = 0;
    const q = [0];
    while (q.length) {
      const x = q.shift();
      for (let y = 0; y < 11; y++)
        if (prev[y] < 0 && C[x][y] > 0) {
          prev[y] = x;
          q.push(y);
        }
    }
    if (prev[10] < 0) break;
    let b = Infinity;
    for (let y = 10; y !== 0; y = prev[y]) b = Math.min(b, C[prev[y]][y]);
    for (let y = 10; y !== 0; y = prev[y]) {
      C[prev[y]][y] -= b;
      C[y][prev[y]] += b;
    }
    flow += b;
  }
  return Math.max(0, sum(f) - flow) + Math.abs(sum(f) - sum(col));
}

function pairRows(rng, mslots, plan, aStar, st) {
  const cost = (sg) => {
    const tg = Array(6).fill(0);
    const ton = Array(6).fill(0);
    for (let r = 0; r < N; r++)
      for (let j = 0; j < 3; j++) {
        const ty = plan.types[r][j];
        if (ty > 1) continue;
        const s = mslots[sg[r]][plan.perm[r][j]];
        tg[s]++;
        if (ty === T_ON) ton[s]++;
      }
    let hard = flowShortfall(mslots, plan, sg);
    for (let s = 0; s < 6; s++) hard += Math.abs(tg[s] - 3) + Math.abs(ton[s] - aStar[s]);
    return hard;
  };
  for (let rs = 0; rs < 30; rs++) {
    st.pairRestarts++;
    const sg = rng.shuffle(range(N));
    let c = cost(sg);
    for (let step = 0; step < 3000 && c > 0; step++) {
      const a = rng.int(N);
      const b = rng.int(N);
      if (a === b) continue;
      [sg[a], sg[b]] = [sg[b], sg[a]];
      const nc = cost(sg);
      if (nc <= c) c = nc;
      else [sg[a], sg[b]] = [sg[b], sg[a]];
    }
    if (c === 0) return sg;
  }
  fail('pairing');
}

/* ---------- shade: assigned to the plan ROWS, so that probe type x shade (x test position) is balanced ---------- */
const SUB6 = (() => {
  const out = [];
  for (let m = 0; m < 4096; m++) {
    let c = 0;
    for (let i = 0; i < N; i++) c += (m >> i) & 1;
    if (c === N / 2) out.push(m);
  }
  return out;
})();

/* Which 6 of the 12 rows get shade 1. Half A: every probe type 4 or 5 times, every (type, test position)
 * 1 or 2 times among the shade-1 rows. Half B: the complement of half A's matrix cell by cell (3 - a), so
 * the pool has 9 / 3 per cell. Returns null when this plan admits no such subset (a new plan is drawn). */
function assignShade(rng, plan, prevW) {
  const good = [];
  for (const m of SUB6) {
    const W = range(4).map(() => [0, 0, 0]);
    for (let r = 0; r < N; r++)
      if ((m >> r) & 1) for (let j = 0; j < 3; j++) W[plan.types[r][j]][j]++;
    const ok = prevW
      ? W.every((row, k) => row.every((x, j) => x === 3 - prevW[k][j]))
      : W.every((row) => sum(row) === 4 || sum(row) === 5) &&
        W.flat().every((x) => x === 1 || x === 2);
    if (ok) good.push([m, W]);
  }
  if (!good.length) return null;
  const [m, W] = good[rng.int(good.length)];
  return { rowShade: range(N).map((r) => (m >> r) & 1), W };
}

/* ---------- exact randomised DFS label solver ---------- */
/* items: [{t, slot, ord, fixed: 0|1|null}]. Returns 0/1 labels aligned to items such that: every serial
 * slot has `perSlotOn` on, every ordinal has `ordTarget` on, every group g (e.g. rotation stratum, shade)
 * has `groups[g].target[k]` on in its class k (`of[t]` = class of trial t), and the trial on-counts have
 * the histogram `hist`. Trials are placed one at a time in random order, trying their allowed on/off
 * patterns in random order, with the remaining need / potential of every family as the pruning rule;
 * a node cap turns a stuck search into a Retry. */
function solveDFS(rng, items, { perSlotOn, ordTarget, groups = [], hist }, st, maxNodes = 4000) {
  const need = [];
  const pot = [];
  const addFam = (target) => {
    need.push(target);
    pot.push(0);
    return need.length - 1;
  };
  const slotF = range(6).map(() => addFam(perSlotOn));
  const ordF = range(3).map(() => addFam(ordTarget));
  const grpF = groups.map((g) => g.target.map((t) => addFam(t)));
  const famOf = items.map((it) => [
    slotF[it.slot],
    ordF[it.ord],
    ...groups.map((g, gi) => grpF[gi][g.of[it.t]]),
  ]);
  items.forEach((it, i) => {
    if (it.fixed !== 0) famOf[i].forEach((f) => pot[f]++);
  });
  const byT = range(N).map(() => []);
  items.forEach((it, i) => byT[it.t].push(i));
  const options = byT.map((ix) => {
    const o = [];
    for (let m = 0; m < 8; m++)
      if (ix.every((i, k) => items[i].fixed === null || items[i].fixed === ((m >> k) & 1)))
        o.push(m);
    return o;
  });
  const cnt = [0, 0, 0, 0];
  const lab = Array(items.length).fill(0);
  let nodes = 0;
  const pc = (m) => (m & 1) + ((m >> 1) & 1) + ((m >> 2) & 1);
  const rec = (order, d) => {
    if (d === N) return true;
    if (++nodes > maxNodes) return false;
    const t = order[d];
    const ix = byT[t];
    for (const m of rng.shuffle(options[t].slice())) {
      const c = pc(m);
      if (cnt[c] >= hist[c]) continue;
      const touched = [];
      let ok = true;
      ix.forEach((i, k) => {
        const on = (m >> k) & 1;
        const wasPot = items[i].fixed !== 0;
        famOf[i].forEach((f) => {
          if (on) need[f]--;
          if (wasPot) pot[f]--;
          touched.push([f, on, wasPot]);
        });
      });
      for (const [f] of touched)
        if (need[f] < 0 || need[f] > pot[f]) {
          ok = false;
          break;
        }
      if (ok) {
        cnt[c]++;
        ix.forEach((i, k) => (lab[i] = (m >> k) & 1));
        if (rec(order, d + 1)) return true;
        cnt[c]--;
      }
      for (const [f, on, wasPot] of touched) {
        if (on) need[f]++;
        if (wasPot) pot[f]++;
      }
    }
    return false;
  };
  const ok = need.every((x, f) => x >= 0 && x <= pot[f]) && rec(rng.shuffle(range(N)), 0);
  st.dfsNodes += nodes;
  if (!ok) fail('label dfs');
  return lab;
}

/* ---------- rotation strata assigned AFTER the memory labels ---------- */
/* Pairs of trials whose memory on-counts sum to 3 ((0,3) and (1,2)); a uniformly random such matching
 * (the histogram (2,4,4,2) / (1,5,5,1) guarantees one exists), the pairs in random order for the six
 * strata, the stratum's two angles in random order. => 3 on-pattern memory items per stratum. */
function assignStrataByMemory(rng, memOn, angles) {
  const byCount = (k) => rng.shuffle(range(N).filter((t) => memOn[t] === k));
  const [z, o, tw, th] = [0, 1, 2, 3].map(byCount);
  if (z.length !== th.length || o.length !== tw.length) fail('strata pairing');
  const pairs = rng.shuffle([...z.map((t, i) => [t, th[i]]), ...o.map((t, i) => [t, tw[i]])]);
  const out = Array(N).fill(null);
  pairs.forEach(([a, b], k) => {
    const two = rng.shuffle([angles[2 * k], angles[2 * k + 1]]);
    out[a] = two[0];
    out[b] = two[1];
  });
  return out;
}

/* ---------- pool-level draws ---------- */
/**
 * Everything that is decided once per 24-trial pool and shared by its two halves:
 * which complement pair each half leaves out, the per-slot T_on pattern (a / 3 - a),
 * the 4 angles of every stratum split 2 / 2 (listed stratum by stratum: entries 2k and
 * 2k + 1 belong to stratum k), the on-count histogram of each half, the targets-per-trial histogram of each half
 * (drawn independently of the on-count one), and (after half A
 * is generated) its probe-type x test-position x shade matrix, which half B complements.
 */
export function drawPoolPlan(type, rng) {
  if (!BALANCED_TYPES.includes(type)) throw new Error(`drawPoolPlan: unknown trial type '${type}'`);
  const aPat = rng.shuffle([2, 2, 2, 1, 1, 1]);
  const angles = [[], []];
  ROTATION_STRATA.forEach(([lo, hi]) => {
    const v = [];
    for (let a = lo; a <= hi; a++) v.push(a);
    const four = rng.shuffle(v).slice(0, 4);
    angles[0].push(four[0], four[1]);
    angles[1].push(four[2], four[3]);
  });
  if (rng.int(2)) angles.reverse();
  const omitA = OMITTABLE[rng.int(OMITTABLE.length)];
  const rest = OMITTABLE.filter((x) => x !== omitA);
  const omitB = rest[rng.int(rest.length)];
  return {
    type,
    hist: rng.int(2)
      ? [
          [2, 4, 4, 2],
          [1, 5, 5, 1],
        ]
      : [
          [1, 5, 5, 1],
          [2, 4, 4, 2],
        ],
    thist: rng.int(2)
      ? [
          [2, 4, 4, 2],
          [1, 5, 5, 1],
        ]
      : [
          [1, 5, 5, 1],
          [2, 4, 4, 2],
        ],
    omit: [omitA, omitB],
    aPat: [aPat, aPat.map((x) => 3 - x)],
    angles,
    shadeW: null,
  };
}

/* ---------- one half, one attempt ---------- */
function genHalfOnce(rng, ps, b, st) {
  const type = ps.type;
  /* 1. sequences: the 6 complement pairs this half keeps, 12 distinct strings */
  const seqs = rng.shuffle(PAIRS.filter((_, i) => i !== ps.omit[b]).flatMap(([x, y]) => [x, y]));
  const mslots = seqs.map((s) => range(6).filter((i) => s[i] === 'M'));
  const sslots = seqs.map((s) => range(6).filter((i) => s[i] === 'S'));
  /* 2. probe plan (rows), the shade of every row, the pairing of rows with sequences */
  let plan = null;
  let rowShade = rng.shuffle([...Array(N / 2).fill(0), ...Array(N / 2).fill(1)]);
  let shadeW = null;
  const rowOfTrial = Array(N).fill(null);
  if (hasMemory(type)) {
    for (let k = 0; plan === null; k++) {
      if (k >= 40) fail('row attributes');
      const cand = genProbePlan(rng, st, ps.thist[b]);
      const r = assignShade(rng, cand, ps.shadeW);
      if (!r) {
        st.attrRetry++;
        continue;
      }
      plan = cand;
      rowShade = r.rowShade;
      shadeW = r.W;
    }
    const sg = pairRows(rng, mslots, plan, ps.aPat[b], st); /* plan row r -> trial sg[r] */
    sg.forEach((t, r) => (rowOfTrial[t] = r));
  }
  const shadeOf = range(N).map((t) =>
    rowOfTrial[t] === null ? rowShade[t] : rowShade[rowOfTrial[t]]
  );
  /* 3. memory labels first (exact slot / ordinal / shade / histogram), then the rotation strata
   *    as pairs of trials whose memory on-counts sum to 3 */
  const memLabels = range(N).map(() => [null, null, null]);
  let angles = Array(N).fill(null);
  const needAngles = hasRotation(type);
  if (hasMemory(type)) {
    const items = [];
    for (let t = 0; t < N; t++) {
      const r = rowOfTrial[t];
      const fixed = [null, null, null];
      for (let j = 0; j < 3; j++) {
        const ty = plan.types[r][j];
        if (ty === T_ON) fixed[plan.perm[r][j]] = 1;
        if (ty === T_OFF) fixed[plan.perm[r][j]] = 0;
      }
      for (let e = 0; e < 3; e++) items.push({ t, slot: mslots[t][e], ord: e, fixed: fixed[e] });
    }
    const lab = solveDFS(
      rng,
      items,
      { perSlotOn: 3, ordTarget: 6, groups: [{ of: shadeOf, target: [9, 9] }], hist: ps.hist[b] },
      st
    );
    items.forEach((it, i) => (memLabels[it.t][it.ord] = lab[i]));
    if (needAngles) angles = assignStrataByMemory(rng, memLabels.map(sum), ps.angles[b]);
  } else if (needAngles) {
    /* no memory labels to pair on: the six strata get their two angles on random trials */
    const order = rng.shuffle(range(N));
    order.forEach((t, i) => (angles[t] = ps.angles[b][i]));
  }
  const strataOf = angles.map((a) => (a === null ? 0 : rotationStratumIndex(a)));
  /* 4. star labels (exact slot / ordinal / stratum / shade / histogram) */
  const starLabels = range(N).map(() => [null, null, null]);
  if (hasStars(type)) {
    const items = [];
    for (let t = 0; t < N; t++)
      for (let k = 0; k < 3; k++) items.push({ t, slot: sslots[t][k], ord: k, fixed: null });
    const lab = solveDFS(
      rng,
      items,
      {
        perSlotOn: 3,
        ordTarget: 6,
        groups: [
          { of: strataOf, target: Array(6).fill(3) },
          { of: shadeOf, target: [9, 9] },
        ],
        hist: ps.hist[b],
      },
      st
    );
    items.forEach((it, i) => (starLabels[it.t][it.ord] = lab[i]));
  }
  /* 5. cells: independent draws per trial (cell-draw.js), nothing carried between trials */
  const tone = isTone(type);
  const out = [];
  for (let t = 0; t < N; t++) {
    const ty = hasMemory(type) ? plan.types[rowOfTrial[t]] : null;
    const used = new Set();
    let memory_items = null;
    let probes = null;
    let stars = null;
    let foils = { on: [], off: [] };
    if (hasMemory(type)) {
      const onC = sum(memLabels[t]);
      const enc = drawEncodedCells(rng, tone, onC);
      const q = { 1: rng.shuffle(enc.on.slice()), 0: rng.shuffle(enc.off.slice()) };
      memory_items = range(3).map((e) =>
        Object.freeze({
          slot_index_in_seq: mslots[t][e],
          encoding_position: e,
          cell: q[memLabels[t][e]].pop(),
          pattern_label: memLabels[t][e] ? 'on' : 'off',
        })
      );
      memory_items.forEach((m) => used.add(m.cell));
      foils = drawFoilCells(
        rng,
        tone,
        enc,
        onC,
        ty.filter((x) => x === F_ON).length,
        ty.filter((x) => x === F_OFF).length
      );
      const fo = { on: foils.on.slice(), off: foils.off.slice() };
      probes = range(3).map((j) => {
        const e = plan.perm[rowOfTrial[t]][j];
        const T = ty[j];
        const cell = T <= 1 ? memory_items[e].cell : T === F_ON ? fo.on.pop() : fo.off.pop();
        return Object.freeze({
          probe_position: j,
          encoding_position: e,
          type: TYPE_NAMES[T],
          cell,
          is_target: T <= 1,
          pattern_label: T === T_ON || T === F_ON ? 'on' : 'off',
        });
      });
      probes.forEach((p) => used.add(p.cell));
    }
    if (hasStars(type)) {
      const sl = starLabels[t];
      const nOn = sum(sl);
      const cells = drawStarCells(rng, used, nOn, 3 - nOn);
      const q = { 1: cells.on.slice(), 0: cells.off.slice() };
      stars = range(3).map((k) =>
        Object.freeze({
          slot_index_in_seq: sslots[t][k],
          probe_position: k,
          cell: q[sl[k]].pop(),
          pattern_label: sl[k] ? 'on' : 'off',
          is_on_pattern: !!sl[k],
        })
      );
      stars.forEach((x) => used.add(x.cell));
    }
    /* Dummies (open squares) fill the slots the modality-less task leaves empty. */
    const dslots = hasStars(type) ? (hasMemory(type) ? [] : mslots[t]) : sslots[t];
    const dp = drawDummyCells(rng, used, dslots.length);
    const dummies = dslots.map((s, i) => Object.freeze({ slot_index_in_seq: s, cell: dp[i] }));
    const o = {
      trial_type: type,
      trial_index_in_block: t,
      background_shade: BACKGROUND_SHADES[shadeOf[t]],
    };
    if (angles[t] !== null)
      o[type === 'd_only' ? 'display_rotation_deg' : 'rotation_deg'] = angles[t];
    o.sequence = seqs[t];
    if (memory_items) o.memory_items = Object.freeze(memory_items);
    if (stars) o.stars = Object.freeze(stars);
    if (dummies.length) o.dummies = Object.freeze(dummies);
    if (probes) o.probes = Object.freeze(probes);
    out.push(o);
  }
  return { trials: out, shadeW };
}

export function newGenerationStats() {
  return {
    planTries: 0,
    pairRestarts: 0,
    dfsNodes: 0,
    attrRetry: 0,
    halfAttempts: 0,
    halves: 0,
    poolAttempts: 0,
    fails: {},
  };
}

/**
 * Both halves of one condition's pool.
 * Half A is drawn first; half B is drawn conditioned on A (other omitted pair,
 * complementary T_on pattern, other histogram, other 2 angles per stratum,
 * complementary probe-type x position x shade matrix). A half whose search does not
 * converge is redrawn from the same stream (at most MAX_HALF_TRIES draws); if a
 * half cannot be completed the pool is redrawn (at most MAX_POOL_TRIES), after
 * which the call throws.
 *
 * @param {string} type
 * @param {{shuffle:Function,int:Function}} rng   seeded PRNG
 * @param {{stats?: object, budget?: object}} [opts]  budget: see createAttemptBudget
 * @returns {{halfA: object[], halfB: object[]}}  frozen trial-parameter objects;
 *   halfA has trial_index_in_block 0..11, halfB 12..23 (index in the 24-trial pool)
 */
export function generateBalancedPool(type, rng, { stats, budget } = {}) {
  const st = stats ?? newGenerationStats();
  let lastError;
  for (let poolTry = 0; poolTry < MAX_POOL_TRIES; poolTry++) {
    budget?.spend('pool attempt');
    st.poolAttempts++;
    const ps = drawPoolPlan(type, rng);
    try {
      const halves = [];
      for (let b = 0; b < 2; b++) {
        let done = null;
        for (let tries = 1; done === null; tries++) {
          budget?.spend('half attempt');
          st.halfAttempts++;
          try {
            const r = genHalfOnce(rng, ps, b, st);
            done = r.trials;
            if (b === 0) ps.shadeW = r.shadeW;
            st.halves++;
          } catch (e) {
            if (!(e instanceof Retry)) throw e;
            st.fails[e.message] = (st.fails[e.message] || 0) + 1;
            lastError = e;
            if (tries >= MAX_HALF_TRIES) throw e;
          }
        }
        halves.push(done);
      }
      const [a, b] = halves;
      const frozen = (list, offset) =>
        list.map((t) =>
          Object.freeze({ ...t, trial_index_in_block: t.trial_index_in_block + offset })
        );
      return { halfA: frozen(a, 0), halfB: frozen(b, N) };
    } catch (e) {
      if (!(e instanceof Retry)) throw e;
      lastError = e;
    }
  }
  throw new Error(
    `generateBalancedPool(${type}): no exact pool in ${MAX_POOL_TRIES} tries (${lastError?.message})`
  );
}
